-- PixelRP: the Victoria pack's new pieces, in Builders > Customs > Victorians > Victorianos II.
--
-- 5 pieces added to the Victorians set: four windows and a black
-- corner block that clicks through five sizes. Generated by
-- docker/nitro/import-pack-tree.py.
--
-- The download (Victoria, 55 bundles) is mostly furni we already sell - the
-- same art pixel for pixel - so only these are new. Titles were written from
-- the art; the classnames are Dutch (raampje, a small window).
--
-- The rendering half is the .nitro bundles, the icons and the FurnitureData
-- entries under nitro/overrides/; the rows below are inert without them.
--
-- Everything is free - the catalog has been since 90_FreeCatalog.
--
-- Idempotent: fixed id ranges, cleared before insert. Sold on an existing page;
-- no page is made.


DELETE FROM `catalog_items` WHERE `item_id` BETWEEN 113600 AND 113604;
DELETE FROM `furniture` WHERE `id` BETWEEN 113600 AND 113604;


